hints:
```
count frequency of each character in s
for each character with freq > 0:
    if freq is odd:
        add 1 to answer
    else:
        add 2 to answer
return answer
```

code.cpp:
class Solution {
public:
    int minimumLength(string s) {
        int freq[26] = {0};
        for (char c : s) {
            freq[c - 'a']++;
        }
        int ans = 0;
        for (int i = 0; i < 26; i++) {
            if (freq[i] == 0) continue;
            if (freq[i] % 2 == 1) {
                ans += 1;
            } else {
                ans += 2;
            }
        }
        return ans;
    }
};
